}
```

Then in `handleRequest`, after authorization and cookie setting but before serving screen HTML, detect a valid query key on root:

```js
function queryKey(url) {
  const q = url.indexOf('?');
  if (q < 0) return null;
  return new URLSearchParams(url.slice(q + 1)).get('key');
}
```

